window.actualizarFecha = function(){ var fechaEl = document.getElementById('agro-fecha'); var diaEl = document.getElementById('agro-dia'); var infoEl = document.getElementById('print-info-line'); var nombreEl = document.getElementById('agro-nombre'); if(!fechaEl) return; var val = fechaEl.value; if(!val) return; var partes = val.split('-'); var d = new Date(parseInt(partes[0]), parseInt(partes[1])-1, parseInt(partes[2])); var dia = diasSemana()[d.getDay()]; if(diaEl) diaEl.value = dia + ', ' + d.getDate() + '/' + (d.getMonth()+1) + '/' + d.getFullYear(); if(infoEl) { infoEl.textContent = ((nombreEl && nombreEl.value) || '') + ' — ' + dia + ' ' + d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear(); }
}; // -- FUNCIONES PARA DISTRIBUCIÓN TIENDONA --
window.onDistritoChangeDescargas = function(){ var distritoEl = document.getElementById('new-desc-distrito'); var agroInput = document.getElementById('new-desc-agromercado'); var datalist = document.getElementById('dl-agros'); if (!distritoEl || !agroInput || !datalist) return; var distrito = distritoEl.value; agroInput.value = ''; datalist.innerHTML = ''; if (!distrito) { agroInput.placeholder = 'Seleccione distrito primero...'; return; } agroInput.placeholder = 'Seleccione o escriba agromercado...'; var lista = []; // Agromercados base desde AGROMERCADOS_DATA (AGROMERCADOS_DATA[distrito] || []).forEach(function(e){ if (e && e.a) lista.push(e.a); }); // Agromercados agregados manualmente var customData = getCustomDistribucionData ? getCustomDistribucionData() : {}; (customData[distrito] || []).forEach(function(e){ if (e && e.a && (!e.tipo || e.tipo === 'TIENDONA')) lista.push(e.a); }); // Quitar duplicados y pintar datalist lista = Array.from(new Set(lista.filter(Boolean))).sort(); lista.forEach(function(nombre){ var option = document.createElement('option'); option.value = nombre; datalist.appendChild(option); }); console.log('Agromercados Tiendona cargados:', distrito, lista);
}; // -- FUNCIONES PARA DISTRIBUCIÓN CDA --
window.onDistritoChangeDistribucion = function(){ // Validar existencia de elementos var distritoEl = document.getElementById('distribucion-distrito'); var aInput = document.getElementById('distribucion-agromercado'); if (!distritoEl || !aInput) return; var distrito = distritoEl.value; aInput.value = ''; aInput.placeholder = !distrito ? 'Seleccione distrito primero...' : 'Nombre del agromercado...'; if(!distrito) return; // Filtrar agromercados CDA para este distrito var entries = (AGROMERCADOS_DATA[distrito]||[]).filter(function(e){ return e.tipo === 'CDA'; }); // Actualizar datalist solo con agromercados CDA var datalist = document.getElementById('dl-agros'); if (datalist) { // Guardar opciones originales si no están guardadas if (!window.originalDlAgros) { window.originalDlAgros = Array.from(datalist.children).map(opt =>opt.value); } // Limpiar y agregar solo agromercados CDA datalist.innerHTML = ''; entries.forEach(function(e){ var option = document.createElement('option'); option.value = e.a; datalist.appendChild(option); }); }
}; // -- FUNCIONES PARA AGREGAR DATOS PERSONALIZADOS -- // Obtener datos personalizados
window.getCustomDistribucionData = function(){ try { return JSON.parse(localStorage.getItem('distribucion-custom-data') || '{}'); } catch(e) { return {}; }
}; // Guardar datos personalizados
window.saveCustomDistribucionData = function(data){ localStorage.setItem('distribucion-custom-data', JSON.stringify(data));
}; // Agregar nuevo distrito
window.agregarDistritoDistribucion = function(){ var nombre = prompt('Nombre del nuevo distrito:'); if(!nombre || nombre.trim() === '') { alert('El nombre del distrito no puede estar vacío.'); return; } nombre = nombre.trim().toUpperCase().replace(/\s+/g, ' '); // Verificar si ya existe en datos originales o personalizados if(AGROMERCADOS_DATA[nombre]) { alert('Este distrito ya existe.'); return; } var customData = getCustomDistribucionData(); if(customData[nombre]) { alert('Este distrito ya existe en datos personalizados.'); return; } // Agregar a datos personalizados customData[nombre] = []; saveCustomDistribucionData(customData); // Actualizar ambos selectores actualizarSelectoresDistrito(nombre); alert('Distrito "' + nombre + '" agregado correctamente.');
}; // Agregar nuevo municipio a un distrito
window.agregarMunicipioDistribucion = function(){ var distritoEl = document.getElementById('distribucion-distrito') || document.getElementById('new-desc-distrito'); if(!distritoEl || !distritoEl.value) { alert('Seleccione un distrito primero.'); return; } var distrito = distritoEl.value; var nombre = prompt('Nombre del nuevo municipio para ' + distrito + ':'); if(!nombre || nombre.trim() === '') { alert('El nombre del municipio no puede estar vacío.'); return; } nombre = nombre.trim().toUpperCase().replace(/\s+/g, ' '); var customData = getCustomDistribucionData(); var distritoData = customData[distrito] || []; // Verificar si ya existe var existe = distritoData.some(function(e){ return e.m === nombre; }); if(existe) { alert('Este municipio ya existe en ' + distrito + '.'); return; } // Agregar municipio sin agromercados todavía distritoData.push({m: nombre, tipo: 'CUSTOM'}); customData[distrito] = distritoData; saveCustomDistribucionData(customData); // Actualizar selector de municipios actualizarSelectoresMunicipio(distrito, nombre); alert('Municipio "' + nombre + '" agregado a ' + distrito + '.');
}; // Agregar nuevo agromercado
window.agregarAgromercadoDistribucion = function(){ var distritoEl = document.getElementById('distribucion-distrito') || document.getElementById('new-desc-distrito'); if(!distritoEl || !distritoEl.value) { alert('Seleccione un distrito primero.'); return; } var distrito = distritoEl.value; var nombre = prompt('Nombre del nuevo agromercado para ' + distrito + ':'); if(!nombre || nombre.trim() === '') { alert('El nombre del agromercado no puede estar vacío.'); return; } nombre = nombre.trim().toUpperCase().replace(/\s+/g, ' '); // Determinar tipo según pestaña activa var tipo = document.getElementById('tab-distribucion').classList.contains('active') ? 'CDA' : 'TIENDONA'; var customData = getCustomDistribucionData(); var distritoData = customData[distrito] || []; // Verificar si ya existe var existe = distritoData.some(function(e){ return e.a === nombre && e.tipo === tipo; }); if(existe) { alert('Este agromercado ya existe en ' + distrito + '.'); return; } // Agregar agromercado sin municipio distritoData.push({m: '', a: nombre, tipo: tipo}); customData[distrito] = distritoData; saveCustomDistribucionData(customData); // Actualizar datalist actualizarDatalistAgromercados(distrito, tipo); alert('Agromercado "' + nombre + '" agregado a ' + distrito + '.');
}; // Funciones auxiliares para actualizar selectores
window.actualizarSelectoresDistrito = function(nombre){
  var cdaSelect = document.getElementById('distribucion-distrito');
  if (cdaSelect && !Array.from(cdaSelect.options).some(function(opt){ return opt.value === nombre; })) {
    var optionCda = document.createElement('option');
    optionCda.value = nombre;
    optionCda.textContent = nombre;
    cdaSelect.appendChild(optionCda);
  }
  var tiendaSelect = document.getElementById('new-desc-distrito');
  if (tiendaSelect && !Array.from(tiendaSelect.options).some(function(opt){ return opt.value === nombre; })) {
    var optionTienda = document.createElement('option');
    optionTienda.value = nombre;
    optionTienda.textContent = nombre;
    tiendaSelect.appendChild(optionTienda);
  }
};
window.actualizarDatalistAgromercados = function(distrito, tipo){
  var datalist = document.getElementById('dl-agros');
  if(!datalist) return;
  var customData = getCustomDistribucionData();
  var entries = (customData[distrito] || []).filter(function(e){ return e.tipo === tipo; });
  entries.forEach(function(e){
    if(!Array.from(datalist.children).some(function(opt){ return opt.value === e.a; })) {
      var option = document.createElement('option');
      option.value = e.a;
      datalist.appendChild(option);
    }
  });
};
// -- CALCULAR --
window.calcular = function(){
  var totalVenta = 0;
  PRODUCTOS.forEach(function(p){
    var inventarioAnterior = n(p+'-ant');
    var mercaderiaNueva = n(p+'-nueva');
    var inventarioInicio = inventarioAnterior + mercaderiaNueva;
    var ventasDia = n(p+'-ven');
    var faltantes = n(p+'-fal');
    var productoDanado = n(p+'-dan');
    setVal(p+'-ini', inventarioInicio);
    var disponibilidad = inventarioInicio - ventasDia - faltantes - productoDanado;
    var disponibilidadFinal = disponibilidad < 0 ? 0 : disponibilidad;
    var disElement = document.getElementById(p+'-dis');
    if(disElement) {
      disElement.value = disponibilidadFinal;
      disElement.dispatchEvent(new Event('change', { bubbles: true }));
    }
    var dineroVenta = p === 'fr4' ? (ventasDia / 4) * PRECIOS[p] : ventasDia * PRECIOS[p];
    setMoney(p+'-din', dineroVenta);
    totalVenta += dineroVenta;
  });
  setMoney('campo-ventas', totalVenta);
  setVal('total-venta-display', '$'+totalVenta.toFixed(2));
  var elKpiVentas = document.getElementById('kpi-ventas');
  if(elKpiVentas) elKpiVentas.textContent = '$'+totalVenta.toFixed(2);
  calcularRemesa();
  calcularCuadre();
  guardarLocal();
};
var calcular = window.calcular;
window.calcularCuadre = function(){
  var ventasCalculadas = parseFloat(document.getElementById('campo-ventas').value.replace('$', '').replace(',', '')) || 0;
  var dineroRemesado = parseFloat(document.getElementById('campo-dinero-remesado').value) || 0;
  var diferencia = +(dineroRemesado - ventasCalculadas).toFixed(2);
  var estado = diferencia === 0 ? 'CUADRADO' : diferencia > 0 ? 'SOBRANTE' : 'FALTANTE';
  setMoney('campo-total-esperado', ventasCalculadas);
  setMoney('campo-diferencia', Math.abs(diferencia));
  var estadoElement = document.getElementById('campo-estado-cuadre');
  if(!estadoElement) return;
  estadoElement.value = estado;
  if (estado === 'FALTANTE') {
    estadoElement.style.background = '#FEE2E2';
    estadoElement.style.borderColor = '#EF4444';
    estadoElement.style.color = '#DC2626';
  } else if (estado === 'SOBRANTE') {
    estadoElement.style.background = '#DBEAFE';
    estadoElement.style.borderColor = '#3B82F6';
    estadoElement.style.color = '#1D4ED8';
  } else {
    estadoElement.style.background = '#F0FDF4';
    estadoElement.style.borderColor = '#86EFAC';
    estadoElement.style.color = '#16A34A';
  }
};
window.calcularRemesa = function(){
  var ventas = 0;
  PRODUCTOS.forEach(function(p){
    var cantidad = n(p+'-ven');
    ventas += p === 'fr4' ? (cantidad / 4) * PRECIOS[p] : cantidad * PRECIOS[p];
  });
  var gastos = parseFloat(document.getElementById('campo-gastos').value) || 0;
  var remesa = ventas - gastos;
  setMoney('campo-remesa', remesa < 0 ? 0 : remesa);
  var elKpiGastos = document.getElementById('kpi-gastos');
  if(elKpiGastos) elKpiGastos.textContent = '$'+gastos.toFixed(2);
  var elKpiRemesa = document.getElementById('kpi-remesa');
  if(elKpiRemesa) elKpiRemesa.textContent = '$'+(remesa < 0 ? 0 : remesa).toFixed(2);
};
window.obtenerIngresosAgromercado = function(agromercado){
  var ingresos = { arroz: 0, precocido: 0, frijol1: 0, frijol4: 0, aceite: 0, harina: 0 };
  if(!agromercado) return ingresos;
  try{
    var inventario = JSON.parse(localStorage.getItem('inventario-data') || '[]');
    var registrosAgromercado = inventario.filter(function(item){
      return item.ubicacion === 'agromercados' && (item.lugar === agromercado || item.agromercado === agromercado);
    });
    registrosAgromercado.forEach(function(registro){
      ingresos.arroz += parseFloat(registro.arroz) || 0;
      ingresos.precocido += parseFloat(registro.precocido) || 0;
      ingresos.frijol1 += parseFloat(registro.frijol1) || 0;
      ingresos.frijol4 += parseFloat(registro.frijol4) || 0;
      ingresos.aceite += parseFloat(registro.aceite) || 0;
      ingresos.harina += parseFloat(registro.harina) || 0;
    });
    var descargas = JSON.parse(localStorage.getItem('descargas-tiendona-historial') || '[]');
    descargas.forEach(function(registro){
      if(registro.datos && Array.isArray(registro.datos)){
        registro.datos.forEach(function(descarga){
          if(descarga.agromercado === agromercado){
            ingresos.arroz += parseFloat(descarga.arroz) || 0;
            ingresos.precocido += parseFloat(descarga.arrozPrecocido) || 0;
            ingresos.frijol1 += parseFloat(descarga.frijol1) || 0;
            ingresos.frijol4 += parseFloat(descarga.frijol4) || 0;
            ingresos.aceite += parseFloat(descarga.aceite) || 0;
            ingresos.harina += parseFloat(descarga.harina) || 0;
          }
        });
      }
    });
  } catch(e){
    console.error('Error obteniendo ingresos del agromercado:', e);
  }
  return ingresos;
};
// -- CARGAR STOCK AGROMERCADO --
window.cargarStockAgromercado = function(){
  var agromercadoEl = document.getElementById('agro-nombre');
  if (!agromercadoEl) return;
  var agromercadoSeleccionado = agromercadoEl.value;
  if(!agromercadoSeleccionado) return;
  try{
    cargarInventarioAgromercadoSeleccionado?.();
    var stock = window.obtenerIngresosAgromercado(agromercadoSeleccionado);
    setVal('ab1-ini', stock.arroz || 0);
    setVal('ap1-ini', stock.precocido || 0);
    setVal('fr1-ini', stock.frijol1 || 0);
    setVal('fr4-ini', stock.frijol4 || 0);
    setVal('ac-ini', stock.aceite || 0);
    setVal('ha-ini', stock.harina || 0);
    calcular();
  } catch(e){
    console.error('Error cargando stock del agromercado:', e);
  }
};
// -- CARGAR INVENTARIO DEL AGROMERCADO SELECCIONADO --
window.cargarInventarioAgromercadoSeleccionado = function(){
  var agro = document.getElementById('agro-agromercado')?.value?.trim() || document.getElementById('campo-agromercado')?.value?.trim() || document.getElementById('agro-nombre')?.value?.trim() || '';
  if (!agro) return;
  var inv = JSON.parse(localStorage.getItem('inventario-data') || '[]');
  var resumen = { arroz: 0, precocido: 0, frijol1: 0, frijol4: 0, aceite: 0, harina: 0 };
  inv.forEach(function(r){
    if ((r.ubicacion || '').trim() !== agro) return;
    resumen.arroz += Number(r.arroz || 0);
    resumen.precocido += Number(r.precocido || 0);
    resumen.frijol1 += Number(r.frijol1 || 0);
    resumen.frijol4 += Number(r.frijol4 || 0);
    resumen.aceite += Number(r.aceite || 0);
    resumen.harina += Number(r.harina || 0);
  });
  setVal?.('ab1-ant', resumen.arroz);
  setVal?.('ap1-ant', resumen.precocido);
  setVal?.('fr1-ant', resumen.frijol1);
  setVal?.('fr4-ant', resumen.frijol4);
  setVal?.('ac-ant', resumen.aceite);
  setVal?.('ha-ant', resumen.harina);
  calcular?.();
};
// -- LIMPIAR FORMULARIO --
window.limpiarFormulario = function(){
  var agroNombreEl = document.getElementById('agro-nombre');
  var agromercadoSeleccionado = agroNombreEl ? agroNombreEl.value : '';
  PRODUCTOS.forEach(function(p){
    var dis = parseFloat((document.getElementById(p+'-dis')||{}).value)||0;
    setVal(p+'-ant', dis);
    setVal(p+'-ven', 0);
    setVal(p+'-fal', 0);
    setVal(p+'-dan', 0);
  });
  if(agromercadoSeleccionado && typeof obtenerIngresosAgromercado === 'function'){
    var ingresos = obtenerIngresosAgromercado(agromercadoSeleccionado);
    setVal('ab1-nueva', ingresos.arroz);
    setVal('ap1-nueva', ingresos.precocido);
    setVal('fr1-nueva', ingresos.frijol1);
    setVal('fr4-nueva', ingresos.frijol4);
    setVal('ac-nueva', ingresos.aceite);
    setVal('ha-nueva', ingresos.harina);
  } else {
    PRODUCTOS.forEach(function(p){ setVal(p+'-nueva', 0); });
  }
  var gastosEl = document.getElementById('campo-gastos');
  var fechaEl = document.getElementById('agro-fecha');
  if(gastosEl) gastosEl.value = '0';
  if(fechaEl) fechaEl.value = fechaHoy();
  var bSel = document.getElementById('campo-banco');
  if(bSel) bSel.value = '';
  actualizarFecha();
  calcular();
  showToast('Nuevo día iniciado con el inventario de hoy');
};
