window.toggleDetalleBanco = function(banco) {
  // Convertir banco a texto seguro
  const bancoTexto = typeof banco === 'object' ? (banco.nombre || banco.name || banco.banco || 'SIN BANCO') : String(banco || 'SIN BANCO');
  const bancoId = bancoTexto.replace(/\s+/g, '-').replace(/[^\w-]/g, '').toLowerCase();
  const detalleId = 'detalle-' + bancoId;
  const detalleElement = document.getElementById(detalleId);
  if (detalleElement) {
    detalleElement.classList.toggle('expanded');
  }
};
// CARGAR TEMA GUARDADO AL INICIAR
document.addEventListener('DOMContentLoaded', function() {
  localStorage.removeItem('theme');
  localStorage.setItem('exc_tema_visual', 'claro');
  document.body.classList.remove('theme-verde', 'theme-oscuro');
  document.body.setAttribute('data-theme', 'light');
  const themeIcon = document.getElementById('theme-icon');
  if (themeIcon) { themeIcon.textContent = ''; }
  // Cargar resumen de remesas al iniciar
  cargarResumenRemesas?.();
  cargarOpcionesBancoControlVenta?.();
  if (window.calcularTotalesGenerales) { window.calcularTotalesGenerales(); }
  actualizarResumenRemesasDia?.();
  // Actualizar clasificación de agromercados al iniciar
  setTimeout(function(){
    var actualizados = actualizarClasificacionAgromercados();
    if (actualizados > 0) {
      console.log('Se clasificaron ' + actualizados + ' agromercados como CDA/TIENDONA');
    }
  }, 500);

}); 